const refs:Record<string,string>={home:asset('design-reference/01_home.png'),fitness:asset('design-reference/02_fitness.png'),cpa:asset('design-reference/03_cpa.png'),knowledge:asset('design-reference/04_knowledge.png'),timeline:asset('design-reference/05_timeline.png'),capture:asset('design-reference/06_quick_capture.png'),goals:asset('design-reference/07_goals.png'),note:asset('design-reference/08_note_detail.png'),profile:asset('design-reference/09_profile.png'),templates:asset('design-reference/10_templates.png'),tags:asset('design-reference/11_tags.png')};
