function BackupDialog({onClose,onMessage}:{onClose:()=>void;onMessage:(message:string)=>void}){
  const [busy,setBusy]=useState(''),[progress,setProgress]=useState(''),[file,setFile]=useState<File>(),[summary,setSummary]=useState<BackupSummary>(),[error,setError]=useState('');const input=useRef<HTMLInputElement>(null);
  const exportAll=async()=>{try{setBusy('正在创建完整备份');const {blob}=await createBackupZip((current,total)=>setProgress(`${current}/${total}`));downloadBlob(blob,`MYM-Backup-${new Date().toISOString().slice(0,10)}.zip`);onMessage('完整备份已生成');}catch(e){setError(e instanceof Error?e.message:'备份失败');}finally{setBusy('');}};
  const select=async(event:ChangeEvent<HTMLInputElement>)=>{const selected=event.target.files?.[0];if(!selected)return;try{setError('');setBusy('正在验证备份');setFile(selected);setSummary(await inspectBackupZip(selected));}catch(e){setFile(undefined);setSummary(undefined);setError(e instanceof Error?e.message:'备份无效');}finally{setBusy('');}};
  const restore=async()=>{if(!file)return;try{setBusy('正在恢复');await restoreBackupZip(file,(current,total)=>setProgress(`${current}/${total}`));onMessage('备份已完整恢复');onClose();}catch(e){setError(e instanceof Error?e.message:'恢复失败');}finally{setBusy('');}};
  return <Dialog title="备份与恢复" onClose={onClose}><div className="backup-options"><button onClick={exportAll}><Database/><span><b>导出完整 ZIP</b><small>数据库 + 图片 + 视频 + 音频 + 缩略图</small></span></button><button onClick={()=>input.current?.click()}><RefreshCw/><span><b>选择备份恢复</b><small>先验证，确认后才替换数据</small></span></button><input hidden ref={input} type="file" accept=".zip,application/zip" onChange={select}/></div>{busy&&<p className="busy-line">{busy} {progress}</p>}{error&&<p className="error-line">{error}</p>}{summary&&<div className="restore-summary"><h3>发现：</h3><p>{summary.entries} 条记录<br/>{summary.goals} 个目标<br/>{summary.tags} 个标签<br/>{summary.images} 张图片<br/>{summary.videos} 个视频<br/>{summary.audio} 段音频<br/>{summary.knowledge} 个知识节点</p><button className="primary" onClick={restore} disabled={Boolean(busy)}>确认恢复</button></div>}</Dialog>;
}

