  const q=query.trim().toLowerCase();const entryResults=q?entries.filter(x=>[x.title,x.content,...x.tags].some(value=>value?.toLowerCase().includes(q))):[];const other=q?[...goals.map(x=>({kind:'目标',title:x.title})),...lines.map(x=>({kind:'主线',title:x.title})),...templates.map(x=>({kind:'模板',title:x.title}))].filter(x=>x.title.toLowerCase().includes(q)):[];
