  const scan=async()=>{setBusy(true);const result=await findOrphanMedia();if(!result.databaseOrphans.length&&!result.filesystemOrphans.length){onMessage('没有发现未使用媒体');setBusy(false);return;}const count=await cleanOrphanMedia(result);onMessage(`已清理 ${count} 个未使用媒体文件`);setBusy(false);};
  return <Dialog title="本地维护" onClose={onClose}><div className="maintenance-actions"><button onClick={scan} disabled={busy}><Trash2/><span><b>清理未使用媒体</b><small>只清理没有记录或知识节点引用的文件</small></span></button><button onClick={()=>setConfirmSeed(true)}><CircleDot/><span><b>清除示例数据</b><small>删除示例主线与目标，不删除你的记录</small></span></button></div>{confirmSeed&&<div className="inline-confirm"><p>确认删除健身、CPA、英语示例主线及示例目标？</p><button onClick={()=>setConfirmSeed(false)}>取消</button><button className="danger" onClick={async()=>{await clearExampleData();setConfirmSeed(false);onMessage('示例数据已清除')}}>确认清除</button></div>}</Dialog>;
