function TemplateCard({template,onUse,onEdit,onCopy,onMove}:{template:Template;onUse:()=>void;onEdit:()=>void;onCopy:()=>void;onMove:(delta:number)=>void}){const Icon=iconMap[template.icon]??FileText;return <article><div className="template-icon"><Icon/></div><h2>{template.title}</h2><p>{template.description}</p><footer><button onClick={onUse}>使用</button><span><button onClick={onEdit}>编辑</button> · <button onClick={onCopy}>复制</button></span></footer><div className="card-order"><button onClick={()=>onMove(-1)}><ArrowUp/></button><button onClick={()=>onMove(1)}><ArrowDown/></button></div></article>}
function TemplateEditor({value,onClose,onSave,onDelete}:{value:Template;onClose:()=>void;onSave:(value:Template)=>void;onDelete?:()=>void}){
  const [draft,setDraft]=useState(value),[tagText,setTagText]=useState(value.defaultTags.join('，'));
  const updateField=(id:string,patch:Partial<TemplateField>)=>setDraft(current=>({...current,fields:current.fields.map(field=>field.id===id?{...field,...patch}:field)}));
  const addField=()=>setDraft(current=>({...current,fields:[...current.fields,{id:crypto.randomUUID(),label:'新字段',type:'text',order:current.fields.length}]}));
  const moveField=(index:number,delta:number)=>setDraft(current=>{const fields=[...current.fields],target=index+delta;if(target<0||target>=fields.length)return current;[fields[index],fields[target]]=[fields[target],fields[index]];return {...current,fields:fields.map((field,order)=>({...field,order}))}});
  return <Dialog title="编辑模板" onClose={onClose} actions={<>{onDelete&&<button className="danger" onClick={onDelete}>删除</button>}<button className="primary" onClick={()=>onSave({...draft,title:draft.title.trim()||'未命名模板',defaultTags:tagText.split(/[，,]/).map(normalizeTag).filter(Boolean)})}>保存模板</button></>}><div className="form-stack"><label>模板名称<input value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>描述<textarea value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><label>默认标签<input value={tagText} onChange={e=>setTagText(e.target.value)} placeholder="用逗号分隔"/></label></div><div className="field-editor"><div className="section-title"><h3>字段</h3><button onClick={addField}><Plus/> 添加</button></div>{draft.fields.map((field,index)=><article key={field.id}><input aria-label="字段名称" value={field.label} onChange={e=>updateField(field.id,{label:e.target.value})}/><select value={field.type} onChange={e=>updateField(field.id,{type:e.target.value as TemplateFieldType})}>{Object.entries(fieldTypeLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><label><input type="checkbox" checked={field.required||false} onChange={e=>updateField(field.id,{required:e.target.checked})}/> 必填</label>{field.type==='select'&&<input placeholder="选项，用逗号分隔" value={field.options?.join(',')||''} onChange={e=>updateField(field.id,{options:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/>} {(field.type==='number'||field.type==='metric')&&<input placeholder="单位" value={field.unit||''} onChange={e=>updateField(field.id,{unit:e.target.value})}/>}<div><button onClick={()=>moveField(index,-1)}><ArrowUp/></button><button onClick={()=>moveField(index,1)}><ArrowDown/></button><button onClick={()=>setDraft(current=>({...current,fields:current.fields.filter(x=>x.id!==field.id)}))}><Trash2/></button></div></article>)}</div><label className="field-checkbox"><input type="checkbox" checked={draft.sections.includes('补充内容')} onChange={e=>setDraft({...draft,sections:e.target.checked?['补充内容']:[]})}/><span>保留自由补充内容区</span></label></Dialog>;
}

function Tags(){
  const nav=useNavigate();const tags=useLiveQuery(()=>db.tags.toArray(),[])??[];const [query,setQuery]=useState(''),[createOpen,setCreateOpen]=useState(false),[newName,setNewName]=useState(''),[active,setActive]=useState<Tag>(),[mode,setMode]=useState<'menu'|'rename'|'merge'|'delete'>('menu'),[value,setValue]=useState('');
  const close=()=>{setActive(undefined);setMode('menu');setValue('')};const sorted=[...tags].sort((a,b)=>b.count-a.count||b.lastUsedAt.localeCompare(a.lastUsedAt));
  return <Shell noNav className="manage-page tags-page"><PageHeader title="标签管理" onBack={()=>nav(-1)} actions={<button onClick={()=>setCreateOpen(true)}><Plus/></button>}/><div className="manage-pad"><label className="searchbox"><Search/><input placeholder="搜索标签" value={query} onChange={e=>setQuery(e.target.value)}/></label><article className="tag-rule"><small>标签规则</small><p>用过的标签会自动保留；计数和最近使用时间由真实记录重新计算。删除标签不会删除笔记。</p></article><div className="section-title"><h2>全部标签</h2><button onClick={()=>recalculateTagCounts()}>重新统计</button></div><div className="tag-list">{sorted.filter(tag=>tag.name.includes(query.replace(/^#/,''))).map(tag=><div key={tag.id}><b>#{tag.name}</b><span>{tag.count} 条记录</span><button onClick={()=>{setActive(tag);setMode('menu')}}><MoreHorizontal/></button></div>)}</div></div>
    {createOpen&&<Dialog title="创建标签" onClose={()=>setCreateOpen(false)} actions={<button className="primary" onClick={async()=>{await ensureTags([newName]);setCreateOpen(false);setNewName('')}}>创建</button>}><div className="form-stack"><label>标签名称<input autoFocus value={newName} onChange={e=>setNewName(e.target.value)}/></label></div></Dialog>}
    {active&&<Dialog title={`#${active.name}`} onClose={close}>{mode==='menu'?<div className="action-sheet"><button onClick={()=>{setMode('rename');setValue(active.name)}}>重命名</button><button onClick={()=>setMode('merge')}>合并到其他标签</button><button className="danger" onClick={()=>setMode('delete')}>删除</button></div>:mode==='delete'?<div className="confirm-block"><p>只会从记录和模板移除此标签，不会删除任何笔记。</p><button onClick={close}>取消</button><button className="danger" onClick={async()=>{await deleteTag(active.id);close()}}>确认删除</button></div>:<div className="form-stack"><label>{mode==='rename'?'新名称':'合并到'}{mode==='merge'?<select value={value} onChange={e=>setValue(e.target.value)}><option value="">请选择标签</option>{tags.filter(x=>x.id!==active.id).map(tag=><option key={tag.id} value={tag.id}>#{tag.name}</option>)}</select>:<input value={value} onChange={e=>setValue(e.target.value)}/>}</label><button className="primary" onClick={async()=>{if(mode==='rename')await renameTag(active.id,value);else if(value)await mergeTags([active.id],value);close()}}>保存</button></div>}</Dialog>}
  </Shell>;
}

function Overlay(){const location=useLocation();const [opacity,setOpacity]=useState(.5);const enabled=new URLSearchParams(location.search).get('debugOverlay')==='1';if(!enabled)return null;const key=location.pathname.startsWith('/note')?'note':screens[location.pathname]??'home';return <><img className="debug-overlay" style={{opacity}} src={refs[key]} alt="视觉对齐参考"/><div className="overlay-control"><label>Overlay {Math.round(opacity*100)}%</label><input type="range" min="0" max="1" step=".25" value={opacity} onChange={e=>setOpacity(+e.target.value)}/></div></>}

export default function App(){
  const location=useLocation();const fixture=new URLSearchParams(location.search).get('fixture')==='1';
  useEffect(()=>{(async()=>{if(fixture)await ensureVisualFixtures();else await ensureSeedData();await recalculateTagCounts()})();requestPersistentStorage().catch(()=>undefined)},[fixture]);
  return <><Routes><Route path="/" element={<Home/>}/><Route path="/fitness" element={<DomainPage domainId="fitness"/>}/><Route path="/cpa" element={<DomainPage domainId="cpa"/>}/><Route path="/knowledge" element={<Knowledge/>}/><Route path="/timeline" element={<Timeline/>}/><Route path="/capture" element={<QuickCapture/>}/><Route path="/goals" element={<Goals/>}/><Route path="/note/:id" element={<NoteDetail/>}/><Route path="/profile" element={<Profile/>}/><Route path="/templates" element={<Templates/>}/><Route path="/tags" element={<Tags/>}/><Route path="*" element={<Shell><Empty title="页面不存在" description="返回首页继续使用 MYM。"/></Shell>}/></Routes><Overlay/></>;
}
